    "\u56de\u6eaf/\u4f4d\u8fd0\u7b97",
    "\u7ed9\u4f60\u4e00\u4e2a\u957f\u5ea6\u4e3a n \u7684 \u6574\u6570 \u6570\u7ec4 pref \u3002\u627e\u51fa\u5e76\u8fd4\u56de\u6ee1\u8db3\u4e0b\u8ff0\u6761\u4ef6\u4e14\u957f\u5ea6\u4e3a n \u7684\u6570\u7ec4 arr \uff1a\n\n\tpref[i] = arr[0] ^ arr[1] ^ ... ^ arr[i].\n\n\u6ce8\u610f ^ \u8868\u793a \u6309\u4f4d\u5f02\u6216\uff08bitwise-xor\uff09\u8fd0\u7b97\u3002\n\n\u53ef\u4ee5\u8bc1\u660e\u7b54\u6848\u662f \u552f\u4e00 \u7684\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1apref = [5,2,0,3,1]\n\u8f93\u51fa\uff1a[5,7,2,3,2]\n\u89e3\u91ca\uff1a\u4ece\u6570\u7ec4 [5,7,2,3,2] \u53ef\u4ee5\u5f97\u5230\u5982\u4e0b\u7ed3\u679c\uff1a\n- pref[0] = 5\n- pref[1] = 5 ^ 7 = 2\n- pref[2] = 5 ^ 7 ^ 2 = 0\n- pref[3] = 5 ^ 7 ^ 2 ^ 3 = 3\n- pref[4] = 5 ^ 7 ^ 2 ^ 3 ^ 2 = 1\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1apref = [13]\n\u8f93\u51fa\uff1a[13]\n\u89e3\u91ca\uff1apref[0] = arr[0] = 13\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= pref.length <= 105\n\n\t0 <= pref[i] <= 106",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1apref\u3002",
    "\u8f93\u51fa integer[] \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\r\n    def findArray(self, pref: List[int]) -> List[int]:\r\n        ans = [pref[0]]\r\n        for i in range(1, len(pref)):\r\n            ans.append(pref[i] ^ pref[i - 1])\r\n        return ans\r\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.findArray(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
