    "LeetCode 1829",
    "medium",
    "\u56de\u6eaf/\u4f4d\u8fd0\u7b97",
    "\u7ed9\u4f60\u4e00\u4e2a \u6709\u5e8f\u00a0\u6570\u7ec4\u00a0nums\u00a0\uff0c\u5b83\u7531\u00a0n\u00a0\u4e2a\u975e\u8d1f\u6574\u6570\u7ec4\u6210\uff0c\u540c\u65f6\u7ed9\u4f60\u4e00\u4e2a\u6574\u6570\u00a0maximumBit\u00a0\u3002\u4f60\u9700\u8981\u6267\u884c\u4ee5\u4e0b\u67e5\u8be2 n\u00a0\u6b21\uff1a\n\n\t\u627e\u5230\u4e00\u4e2a\u975e\u8d1f\u6574\u6570\u00a0k maximumBit\u00a0\uff0c\u4f7f\u5f97\u00a0nums[0] XOR nums[1] XOR ... XOR nums[nums.length-1] XOR k\u00a0\u7684\u7ed3\u679c \u6700\u5927\u5316\u00a0\u3002k\u00a0\u662f\u7b2c i\u00a0\u4e2a\u67e5\u8be2\u7684\u7b54\u6848\u3002\n\n\t\u4ece\u5f53\u524d\u6570\u7ec4\u00a0nums\u00a0\u5220\u9664\u00a0\u6700\u540e\u00a0\u4e00\u4e2a\u5143\u7d20\u3002\n\n\u8bf7\u4f60\u8fd4\u56de\u4e00\u4e2a\u6570\u7ec4\u00a0answer\u00a0\uff0c\u5176\u4e2d\u00a0answer[i]\u662f\u7b2c\u00a0i\u00a0\u4e2a\u67e5\u8be2\u7684\u7ed3\u679c\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1anums = [0,1,1,3], maximumBit = 2\n\u8f93\u51fa\uff1a[0,3,2,3]\n\u89e3\u91ca\uff1a\u67e5\u8be2\u7684\u7b54\u6848\u5982\u4e0b\uff1a\n\u7b2c\u4e00\u4e2a\u67e5\u8be2\uff1anums = [0,1,1,3]\uff0ck = 0\uff0c\u56e0\u4e3a 0 XOR 1 XOR 1 XOR 3 XOR 0 = 3 \u3002\n\u7b2c\u4e8c\u4e2a\u67e5\u8be2\uff1anums = [0,1,1]\uff0ck = 3\uff0c\u56e0\u4e3a 0 XOR 1 XOR 1 XOR 3 = 3 \u3002\n\u7b2c\u4e09\u4e2a\u67e5\u8be2\uff1anums = [0,1]\uff0ck = 2\uff0c\u56e0\u4e3a 0 XOR 1 XOR 2 = 3 \u3002\n\u7b2c\u56db\u4e2a\u67e5\u8be2\uff1anums = [0]\uff0ck = 3\uff0c\u56e0\u4e3a 0 XOR 3 = 3 \u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1anums = [2,3,4,7], maximumBit = 3\n\u8f93\u51fa\uff1a[5,2,6,5]\n\u89e3\u91ca\uff1a\u67e5\u8be2\u7684\u7b54\u6848\u5982\u4e0b\uff1a\n\u7b2c\u4e00\u4e2a\u67e5\u8be2\uff1anums = [2,3,4,7]\uff0ck = 5\uff0c\u56e0\u4e3a 2 XOR 3 XOR 4 XOR 7 XOR 5 = 7\u3002\n\u7b2c\u4e8c\u4e2a\u67e5\u8be2\uff1anums = [2,3,4]\uff0ck = 2\uff0c\u56e0\u4e3a 2 XOR 3 XOR 4 XOR 2 = 7 \u3002\n\u7b2c\u4e09\u4e2a\u67e5\u8be2\uff1anums = [2,3]\uff0ck = 6\uff0c\u56e0\u4e3a 2 XOR 3 XOR 6 = 7 \u3002\n\u7b2c\u56db\u4e2a\u67e5\u8be2\uff1anums = [2]\uff0ck = 5\uff0c\u56e0\u4e3a 2 XOR 5 = 7 \u3002\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1anums = [0,1,2,2,5,7], maximumBit = 3\n\u8f93\u51fa\uff1a[4,3,6,4,6,7]\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\tnums.length == n\n\n\t1 5\n\n\t1\n\n\t0 maximumBit\n\n\tnums\u200b\u200b\u200b \u4e2d\u7684\u6570\u5b57\u5df2\u7ecf\u6309\u00a0\u5347\u5e8f\u00a0\u6392\u597d\u5e8f\u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1anums\u3001maximumBit\u3002",
    "\u8f93\u51fa integer[] \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def getMaximumXor(self, nums: List[int], maximumBit: int) -> List[int]:\n        n = len(nums)\n        mask = (1 << maximumBit) - 1\n        xorsum = reduce(xor, nums)\n        \n        ans = list()\n        for i in range(n - 1, -1, -1):\n            ans.append(xorsum ^ mask)\n            xorsum ^= nums[i]\n        \n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.getMaximumXor(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
