    "medium",
    "\u56de\u6eaf/\u4f4d\u8fd0\u7b97",
    "\u4e00\u4e2a \u300c\u5f00\u5fc3\u5b57\u7b26\u4e32\u300d\u5b9a\u4e49\u4e3a\uff1a\n\n\t\u4ec5\u5305\u542b\u5c0f\u5199\u5b57\u6bcd\u00a0['a', 'b', 'c'].\n\n\t\u5bf9\u6240\u6709\u5728\u00a01\u00a0\u5230\u00a0s.length - 1\u00a0\u4e4b\u95f4\u7684\u00a0i\u00a0\uff0c\u6ee1\u8db3\u00a0s[i] != s[i + 1]\u00a0\uff08\u5b57\u7b26\u4e32\u7684\u4e0b\u6807\u4ece 1 \u5f00\u59cb\uff09\u3002\n\n\u6bd4\u65b9\u8bf4\uff0c\u5b57\u7b26\u4e32\u00a0\"abc\"\uff0c\"ac\"\uff0c\"b\" \u548c\u00a0\"abcbabcbcb\"\u00a0\u90fd\u662f\u5f00\u5fc3\u5b57\u7b26\u4e32\uff0c\u4f46\u662f\u00a0\"aa\"\uff0c\"baa\"\u00a0\u548c\u00a0\"ababbc\"\u00a0\u90fd\u4e0d\u662f\u5f00\u5fc3\u5b57\u7b26\u4e32\u3002\n\n\u7ed9\u4f60\u4e24\u4e2a\u6574\u6570 n\u00a0\u548c k\u00a0\uff0c\u4f60\u9700\u8981\u5c06\u957f\u5ea6\u4e3a n\u00a0\u7684\u6240\u6709\u5f00\u5fc3\u5b57\u7b26\u4e32\u6309\u5b57\u5178\u5e8f\u6392\u5e8f\u3002\n\n\u8bf7\u4f60\u8fd4\u56de\u6392\u5e8f\u540e\u7684\u7b2c k \u4e2a\u5f00\u5fc3\u5b57\u7b26\u4e32\uff0c\u5982\u679c\u957f\u5ea6\u4e3a n\u00a0\u7684\u5f00\u5fc3\u5b57\u7b26\u4e32\u5c11\u4e8e k\u00a0\u4e2a\uff0c\u90a3\u4e48\u8bf7\u4f60\u8fd4\u56de \u7a7a\u5b57\u7b26\u4e32\u00a0\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1an = 1, k = 3\n\u8f93\u51fa\uff1a\"c\"\n\u89e3\u91ca\uff1a\u5217\u8868 [\"a\", \"b\", \"c\"] \u5305\u542b\u4e86\u6240\u6709\u957f\u5ea6\u4e3a 1 \u7684\u5f00\u5fc3\u5b57\u7b26\u4e32\u3002\u6309\u7167\u5b57\u5178\u5e8f\u6392\u5e8f\u540e\u7b2c\u4e09\u4e2a\u5b57\u7b26\u4e32\u4e3a \"c\" \u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1an = 1, k = 4\n\u8f93\u51fa\uff1a\"\"\n\u89e3\u91ca\uff1a\u957f\u5ea6\u4e3a 1 \u7684\u5f00\u5fc3\u5b57\u7b26\u4e32\u53ea\u6709 3 \u4e2a\u3002\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1an = 3, k = 9\n\u8f93\u51fa\uff1a\"cab\"\n\u89e3\u91ca\uff1a\u957f\u5ea6\u4e3a 3 \u7684\u5f00\u5fc3\u5b57\u7b26\u4e32\u603b\u5171\u6709 12 \u4e2a [\"aba\", \"abc\", \"aca\", \"acb\", \"bab\", \"bac\", \"bca\", \"bcb\", \"cab\", \"cac\", \"cba\", \"cbc\"] \u3002\u7b2c 9 \u4e2a\u5b57\u7b26\u4e32\u4e3a \"cab\"\n```\n\n\u793a\u4f8b 4\uff1a\n\n```\n\u8f93\u5165\uff1an = 2, k = 7\n\u8f93\u51fa\uff1a\"\"\n```\n\n\u793a\u4f8b 5\uff1a\n\n```\n\u8f93\u5165\uff1an = 10, k = 100\n\u8f93\u51fa\uff1a\"abacbabacb\"\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= n <= 10\n\n\t1 <= k <= 100",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1an\u3001k\u3002",
    "\u8f93\u51fa string \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def getHappyString(self, n: int, k: int) -> str:\n        chs = ['a', 'b', 'c']\n        res = []\n        if k > 3 * (1 << (n - 1)):\n            return \"\".join(res)\n        for i in range(n):\n            if len(res) != i:\n                break\n            count = 1 << (n - i - 1)\n            for c in chs:\n                if res and res[-1] == c:\n                    continue\n                if k <= count:\n                    res.append(c)\n                    break\n                k -= count\n        return \"\".join(res)\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.getHappyString(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
