PXM14 = mk(
    "XM14",
    "\u7ec4\u5408\u603b\u548c",
    "LeetCode 39",
    "medium",
    "\u56de\u6eaf/\u4f4d\u8fd0\u7b97",
    "\u7ed9\u4f60\u4e00\u4e2a \u65e0\u91cd\u590d\u5143\u7d20 \u7684\u6574\u6570\u6570\u7ec4\u00a0candidates \u548c\u4e00\u4e2a\u76ee\u6807\u6574\u6570\u00a0target\u00a0\uff0c\u627e\u51fa\u00a0candidates\u00a0\u4e2d\u53ef\u4ee5\u4f7f\u6570\u5b57\u548c\u4e3a\u76ee\u6807\u6570\u00a0target \u7684 \u6240\u6709\u00a0\u4e0d\u540c\u7ec4\u5408 \uff0c\u5e76\u4ee5\u5217\u8868\u5f62\u5f0f\u8fd4\u56de\u3002\u4f60\u53ef\u4ee5\u6309 \u4efb\u610f\u987a\u5e8f \u8fd4\u56de\u8fd9\u4e9b\u7ec4\u5408\u3002\n\ncandidates \u4e2d\u7684 \u540c\u4e00\u4e2a \u6570\u5b57\u53ef\u4ee5 \u65e0\u9650\u5236\u91cd\u590d\u88ab\u9009\u53d6 \u3002\u5982\u679c\u81f3\u5c11\u4e00\u4e2a\u6570\u5b57\u7684\u88ab\u9009\u6570\u91cf\u4e0d\u540c\uff0c\u5219\u4e24\u79cd\u7ec4\u5408\u662f\u4e0d\u540c\u7684\u3002\u00a0\n\n\u5bf9\u4e8e\u7ed9\u5b9a\u7684\u8f93\u5165\uff0c\u4fdd\u8bc1\u548c\u4e3a\u00a0target \u7684\u4e0d\u540c\u7ec4\u5408\u6570\u5c11\u4e8e 150 \u4e2a\u3002\n\n\u00a0\n\n\u793a\u4f8b\u00a01\uff1a\n\n```\n\u8f93\u5165\uff1acandidates = [2,3,6,7], target = 7\n\u8f93\u51fa\uff1a[[2,2,3],[7]]\n\u89e3\u91ca\uff1a\n2 \u548c 3 \u53ef\u4ee5\u5f62\u6210\u4e00\u7ec4\u5019\u9009\uff0c2 + 2 + 3 = 7 \u3002\u6ce8\u610f 2 \u53ef\u4ee5\u4f7f\u7528\u591a\u6b21\u3002\n7 \u4e5f\u662f\u4e00\u4e2a\u5019\u9009\uff0c 7 = 7 \u3002\n\u4ec5\u6709\u8fd9\u4e24\u79cd\u7ec4\u5408\u3002\n```\n\n\u793a\u4f8b\u00a02\uff1a\n\n```\n\u8f93\u5165: candidates = [2,3,5], target = 8\n\u8f93\u51fa: [[2,2,2,2],[2,3,3],[3,5]]\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165: candidates = [2], target = 1\n\u8f93\u51fa: []\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= candidates.length <= 30\n\n\t2 <= candidates[i] <= 40\n\n\tcandidates \u7684\u6240\u6709\u5143\u7d20 \u4e92\u4e0d\u76f8\u540c\n\n\t1 <= target <= 40",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1acandidates\u3001target\u3002",
    "\u8f93\u51fa list<list<integer>> \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:\n        def backtrack(\n            state: list[int], target: int, choices: list[int], start: int, res: list[list[int]]\n        ):\n            \"\"\"\u56de\u6eaf\u7b97\u6cd5\uff1a\u5b50\u96c6\u548c I\"\"\"\n            # \u5b50\u96c6\u548c\u7b49\u4e8e target \u65f6\uff0c\u8bb0\u5f55\u89e3\n            if target == 0:\n                res.append(list(state))\n                return\n            # \u904d\u5386\u6240\u6709\u9009\u62e9\n            # \u526a\u679d\u4e8c\uff1a\u4ece start \u5f00\u59cb\u904d\u5386\uff0c\u907f\u514d\u751f\u6210\u91cd\u590d\u5b50\u96c6\n            for i in range(start, len(choices)):\n                # \u526a\u679d\u4e00\uff1a\u82e5\u5b50\u96c6\u548c\u8d85\u8fc7 target \uff0c\u5219\u76f4\u63a5\u7ed3\u675f\u5faa\u73af\n                # \u8fd9\u662f\u56e0\u4e3a\u6570\u7ec4\u5df2\u6392\u5e8f\uff0c\u540e\u8fb9\u5143\u7d20\u66f4\u5927\uff0c\u5b50\u96c6\u548c\u4e00\u5b9a\u8d85\u8fc7 target\n                if target - choices[i] < 0:\n                    break\n                # \u5c1d\u8bd5\uff1a\u505a\u51fa\u9009\u62e9\uff0c\u66f4\u65b0 target, start\n                state.append(choices[i])\n                # \u8fdb\u884c\u4e0b\u4e00\u8f6e\u9009\u62e9\n                backtrack(state, target - choices[i], choices, i, res)\n                # \u56de\u9000\uff1a\u64a4\u9500\u9009\u62e9\uff0c\u6062\u590d\u5230\u4e4b\u524d\u7684\u72b6\u6001\n                state.pop()\n\n        state = []  # \u72b6\u6001\uff08\u5b50\u96c6\uff09\n        candidates.sort()  # \u5bf9 candidates \u8fdb\u884c\u6392\u5e8f\n        start = 0  # \u904d\u5386\u8d77\u59cb\u70b9\n        res = []  # \u7ed3\u679c\u5217\u8868\uff08\u5b50\u96c6\u5217\u8868\uff09\n        backtrack(state, target, candidates, start, res)\n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.combinationSum(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "exact",
    [["[2,3,6,7]\n7", "[[2,2,3],[7]]"], ["[2,3,5]\n8", "[[2,2,2,2],[2,3,3],[3,5]]"], ["[2]\n1", "[]"]],
    ["array", "backtracking", "\u56de\u6eaf/\u4f4d\u8fd0\u7b97"],
    )
